package utils

import (
	"os"

	"github.com/navidrome/navidrome/log"
)

// IsDirReadable reports whether path can be opened as a directory.
func IsDirReadable(path string) (bool, error) {
	dir, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer func() {
		if err := dir.Close(); err != nil {
			log.Warn("Error closing directory", "path", path, err)
		}
	}()
	return true, nil
}
package utils

import (
	"path/filepath"
	"testing"
)

func TestIsDirReadable(t *testing.T) {
	dir := t.TempDir()
	if readable, err := IsDirReadable(dir); !readable || err != nil {
		t.Fatalf("existing directory: readable=%t, err=%v", readable, err)
	}

	missing := filepath.Join(dir, "missing")
	if readable, err := IsDirReadable(missing); readable || err == nil {
		t.Fatalf("missing directory: readable=%t, err=%v", readable, err)
	}
}
